import{z as n,x as o,o as A,c as C,q as B,j as l,D as a,d as e,s,S as i,b as t}from"./chunks/framework.C8m1ZpeB.js";const L=JSON.parse('{"title":"结构化数据的 RAG","description":"","frontmatter":{"title":"结构化数据的 RAG","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rag-structured-data.md","filePath":"llm/rag-structured-data.md","lastUpdated":1791413859000}'),d={name:"llm/rag-structured-data.md"};function p(m,E,D,S,h,c){const r=o("Mermaid");return A(),C("div",null,[E[2]||(E[2]=B('<h1 id="结构化数据的-rag" tabindex="-1">结构化数据的 RAG <a class="header-anchor" href="#结构化数据的-rag" aria-label="Permalink to &quot;结构化数据的 RAG&quot;">​</a></h1><div class="epigraph"><p>「哪个产品被抱怨物流慢」要语义，「哪个产品退货率最高」要符号引擎；把两类问题喂给同一个向量索引，一半必然答错。</p><footer>—— 据 Yu 等 Spider 的 text-to-SQL 基线与检索工程实践整理</footer></div><p><a href="/llm/rag-query-rewrite-plan">上一课</a>在查询侧装了改写与规划的分级控制。语料里最难的一块是结构化数据：表格、关系库、指标仓。切分课（向量检索与切分）说过表格按逻辑行切、复制表头，那是把表格当文本的极限；本课写越过极限的部分——什么时候拍平、什么时候走 SQL、路由怎么判。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>嵌入空间里没有列约束、类型与聚合这些符号结构。「上季度华东区毛利率最高的产品」对向量检索是灾难：它需要过滤、JOIN、聚合与排序，是查询不是匹配；语义近邻会返回「讲毛利的章节」而不是那行数据。反方向，「哪个产品常被用户抱怨物流慢」需要语义泛化，SQL 写不出「抱怨」。两类问题混在一条向量链上，失败模式互相污染：该精确的模糊了，该模糊的精确不了。缺口是路由与两条各自正确的通路，外加把两者串起来的混合路径。</p><p><span class="marginnote">向量检索的直觉是「按意思找邻居」：擅长「哪些内容在讲这件事」，天生不擅长「算个数再排序」。「毛利率最高」要过滤、分组、比大小，这是数据库的符号引擎的本职。两者像算盘和计算器——各管一类题，硬让一个包场，必有一半算错。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三条路。第一条，文本化走向量：把表序列化——Markdown 行、表头复制进每行、或行叙述化；适合「查行」「找相似案例」类问题；金标沿用切分课（向量检索与切分）的协议，只是跨度变成单元格区间。第二条，text-to-SQL：把 schema 卡（表、列、注释、枚举值、指标口径、few-shot 示例）放进提示，生成 SQL；执行前强制校验——语法、行级权限、LIMIT 上限、超时；评测用执行准确率（金标答案集上比对执行结果），不是字符串匹配。第三条，混合：SQL 先做硬约束筛（时间窗、类目），筛后的小结果集再语义匹配；或先向量找候选实体，再让 SQL 取这些实体的精确指标。路由：规则先行（「最高、平均、增长率、环比」触发 SQL 意图），分类器兜底，两类都拿不准时走混合并降级置信度。</p><p><span class="marginnote">执行校验里的 LIMIT 与超时像保险丝：生成模型偶尔会写出没加限制的全表查询，在千万行大表上一跑几分钟，把整库拖垮。加上「最多返回 100 行、超时 5 秒」这类硬闸后，一条坏 SQL 的代价就从「事故」降级成「返回空结果重试」。</span></p>',9)),(A(),l(i,null,{default:a(()=>[s(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E7%94%A8%E6%88%B7%E9%97%AE%E9%A2%98%22%5D%20--%3E%20R%7B%22%E6%84%8F%E5%9B%BE%E8%B7%AF%E7%94%B1%22%7D%0A%20%20R%20--%3E%7C%E8%AF%AD%E4%B9%89%E5%8C%B9%E9%85%8D%7C%20VEC%5B%22%E6%96%87%E6%9C%AC%E5%8C%96%E8%A1%A8%E6%A0%BC%20%E2%86%92%20%E5%90%91%E9%87%8F%E6%A3%80%E7%B4%A2%22%5D%0A%20%20R%20--%3E%7C%E7%B2%BE%E7%A1%AE%E8%81%9A%E5%90%88%7C%20SQL%5B%22schema%20%E5%8D%A1%20%2B%20text-to-SQL%22%5D%0A%20%20R%20--%3E%7C%E6%8B%BF%E4%B8%8D%E5%87%86%7C%20MIX%5B%22SQL%20%E7%A1%AC%E7%AD%9B%20%2B%20%E8%AF%AD%E4%B9%89%E5%8C%B9%E9%85%8D%22%5D%0A%20%20SQL%20--%3E%20CHK%5B%22%E6%89%A7%E8%A1%8C%E6%A0%A1%E9%AA%8C%EF%BC%9A%E6%9D%83%E9%99%90%20%2F%20LIMIT%20%2F%20%E8%B6%85%E6%97%B6%22%5D%0A%20%20CHK%20--%3E%20ANS%5B%22%E7%BB%93%E6%9E%9C%20%E2%86%92%20%E7%94%9F%E6%88%90%E5%99%A8%E5%B8%A6%E8%A1%A8%E5%BC%95%E7%94%A8%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=t("p",null,"文本化为什么必然丢约束：嵌入把一行压成平均语义，列类型、主外键、聚合语义不在余弦的分辨范围内——它与混合检索同构：词法对标识、向量对改写，这里 SQL 对约束、向量对语义，分工由问题类型定。text-to-SQL 为什么错：主要失败点不是「不会写 SQL」而是 schema linking——问题里的「华东」该对上 region 列的哪个枚举值、「上季度」对哪个日期粒度；所以先补列注释与枚举值清单，再谈提示工程，执行校验挡得住语法错，挡不住「跑通但答非所问」，后者只能靠金标答案集验收。路由为什么规则先行：聚合意图在词汇上有强信号，规则可解释、零延迟、错误可审计；分类器只处理规则的漏网部分。",-1)),(A(),l(i,null,{default:a(()=>[s(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E3%80%8C%E4%B8%8A%E5%AD%A3%E5%BA%A6%E5%8D%8E%E4%B8%9C%E5%8C%BA%E6%AF%9B%E5%88%A9%E7%8E%87%E6%9C%80%E9%AB%98%E7%9A%84%E4%BA%A7%E5%93%81%E3%80%8D%22%5D%20--%3E%20LINK%5B%22schema%20linking%EF%BC%9A%E6%8A%8A%E8%AF%8D%E5%AF%B9%E5%88%B0%E5%88%97%22%5D%0A%20%20W1%5B%22%E4%B8%8A%E5%AD%A3%E5%BA%A6%22%5D%20--%3E%7C%22%E5%AF%B9%E5%93%AA%E4%B8%AA%E6%97%A5%E6%9C%9F%E7%B2%92%E5%BA%A6%EF%BC%9F%22%7C%20G%5B%22DATE_TRUNC%20%E6%8C%89%E5%AD%A3%E8%BF%98%E6%98%AF%E6%8C%89%E6%9C%88%22%5D%0A%20%20W2%5B%22%E5%8D%8E%E4%B8%9C%E5%8C%BA%22%5D%20--%3E%7C%22region%20%E5%88%97%E5%93%AA%E4%B8%AA%E6%9E%9A%E4%B8%BE%E5%80%BC%EF%BC%9F%22%7C%20E%5B%22%E5%86%99%20East%20China%20%E8%BF%98%E6%98%AF%E5%8D%8E%E4%B8%9C%22%5D%0A%20%20W3%5B%22%E6%AF%9B%E5%88%A9%E7%8E%87%22%5D%20--%3E%7C%22%E5%8F%A3%E5%BE%84%E6%80%8E%E4%B9%88%E7%AE%97%EF%BC%9F%22%7C%20M%5B%22%E6%AF%9B%E5%88%A9%E9%99%A4%E4%BB%A5%E6%94%B6%E5%85%A5%EF%BC%8C%E5%88%86%E6%AF%8D%E5%90%AB%E4%B8%8D%E5%90%AB%E9%80%80%E6%AC%BE%22%5D%0A%20%20G%20--%3E%20SQL%5B%22%E6%8B%BC%E8%A3%85%20SQL%22%5D%0A%20%20E%20--%3E%20SQL%0A%20%20M%20--%3E%20SQL%0A%20%20SQL%20--%3E%20CHK%5B%22%E6%89%A7%E8%A1%8C%E6%A0%A1%E9%AA%8C%EF%BC%9A%E5%8F%AA%E6%8C%A1%E8%AF%AD%E6%B3%95%EF%BC%8C%E4%B8%8D%E6%8C%A1%E5%AF%B9%E9%94%99%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=B('<p><span class="marginnote">这张图回答「SQL 明明跑通了为什么还答错」。语法校验只检查 SQL 合不合法，不管「华东」有没有对准数据库里真实存的那个字符串——一个枚举值对不上，查询合法、执行成功、结果全错，且系统毫无报错。这正是要靠金标答案集验收的原因。</span></p><p><span class="marginnote">指标口径必须随 schema 卡给模型：「活跃用户」是按天去重还是按月、退货率分母含不含取消，模型不知道口径时生成的 SQL 语法全对、数字全错——这类错误执行校验永远发现不了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>权限必须下推到 SQL 层的行级安全，提示词里的「请只查你有权的」不是安全边界，与向量侧的权限过滤同一纪律。大表聚合要设超时与扫描上限，防一次提问拖垮库。自由文本备注列仍走向量；半结构化（JSON 日志）介于两者之间，抽取成行再路由。schema 漂移要当发布管理：加列、改枚举值都触发 schema 卡更新与回归题集重跑。文本化表格的切分仍受切分课协议约束——它只是结构化问题里「语义那一半」的权宜。</p><p><span class="marginnote">常见误区：以为在提示里写「请只查你有权限的数据」就是权限控制。对模型来说那只是礼貌建议，它照样可能生成越权 SQL。真正的闸门要装在数据库层——行级安全让越权查询被数据库直接拒绝，这和「门锁在门上」而不是「贴张告示」是一个道理。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>先路由再检索：聚合与约束走 SQL，语义与模糊走向量，拿不准走混合。</li><li>文本化是语义那一半的权宜，列约束与聚合在嵌入空间里不存在。</li><li>text-to-SQL 的主要失败是 schema linking：列注释与枚举清单先于提示工程。</li><li>执行校验挡语法，金标答案集挡答非所问；权限下推行级安全。</li><li>指标口径进 schema 卡；schema 漂移当发布管理。</li><li>出处：Yu 等 Spider；据 text-to-SQL 与检索工程实践整理。</li></ul>',7))])}const u=n(d,[["render",p]]);export{L as __pageData,u as default};
